package com.hmdp.ai.infrastructure.persistence;
import com.fasterxml.jackson.databind.ObjectMapper;import com.hmdp.ai.domain.security.AiPermission;import com.hmdp.ai.domain.tool.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.util.*;
@Repository public class JdbcToolDefinitionRepository implements ToolDefinitionRepository {private final JdbcTemplate jdbc;private final ObjectMapper mapper;public JdbcToolDefinitionRepository(JdbcTemplate jdbc,ObjectMapper mapper){this.jdbc=jdbc;this.mapper=mapper;}@Override public Optional<ToolDefinition> findBound(String tenant,String workspace,String agentId,int agentVersion,String code,int version){List<ToolDefinition>r=jdbc.query("select t.id,t.code,tv.id version_id,tv.version,tv.name,tv.protocol,tv.input_schema,tv.output_schema,tv.risk_level,tv.side_effect,tv.idempotent,tv.timeout_ms,tv.retry_policy_json,tv.required_permissions_json,tv.configuration_json,tv.enabled from ai_agent_version av join ai_agent_tool_binding b on b.agent_version_id=av.id and b.status='ACTIVE' and b.deleted=0 join ai_tool_version tv on tv.id=b.tool_version_id and tv.status='PUBLISHED' and tv.deleted=0 join ai_tool t on t.id=tv.tool_id and t.deleted=0 where av.tenant_id=? and av.workspace_id=? and av.agent_id=? and av.version=? and t.code=? and tv.version=? and av.deleted=0",(rs,row)->new ToolDefinition(rs.getString("id"),rs.getString("version_id"),rs.getString("code"),rs.getInt("version"),rs.getString("name"),ToolProtocol.valueOf(rs.getString("protocol")),rs.getString("input_schema"),rs.getString("output_schema"),ToolRiskLevel.valueOf(rs.getString("risk_level")),rs.getBoolean("side_effect"),rs.getBoolean("idempotent"),rs.getInt("timeout_ms"),rs.getString("retry_policy_json"),permissions(rs.getString("required_permissions_json")),rs.getString("configuration_json"),rs.getBoolean("enabled")),tenant,workspace,agentId,agentVersion,code,version);return r.stream().findFirst();}private List<AiPermission> permissions(String json){try{List<AiPermission>r=new ArrayList<>();for(com.fasterxml.jackson.databind.JsonNode n:mapper.readTree(json))r.add(AiPermission.valueOf(n.asText()));return r;}catch(Exception e){throw new IllegalStateException("stored tool permissions are invalid",e);}}}
